cat > test_weekly.js << 'EOF'
import { monthlyCents, nextCharge } from './src/cycles.js';

// Test weekly plan pricing
const weeklyPlan = { price: 1200, cycle: 'weekly' }; // €12 per week
const monthlyCost = monthlyCents(weeklyPlan);
console.log(`Weekly plan €12/week costs €${(monthlyCost / 100).toFixed(2)} per month`);
console.log(`Expected: €${(12 * 52 / 12).toFixed(2)}`);

// Test weekly plan renewals
const firstCharge = '2026-10-18';
const today = '2026-10-25';
const nextWeeklyCharge = nextCharge({ cycle: 'weekly', since: firstCharge }, today);
console.log(`\nFirst charge: ${firstCharge}`);
console.log(`Today: ${today}`);
console.log(`Next charge: ${nextWeeklyCharge}`);
console.log(`Expected: 2026-10-25 (7 days later)`);

// Test another week
const nextAfter = nextCharge({ cycle: 'weekly', since: firstCharge }, '2026-10-26');
console.log(`\nNext charge after 2026-10-26: ${nextAfter}`);
console.log(`Expected: 2026-11-01 (14 days from start)`);
EOF
node test_weekly.js
